USE CATALOG IDENTIFIER(:catalog);

-- payment_mix: NVL -> coalesce, DECODE -> CASE, NVL2 -> if(x IS NOT NULL, ...).
-- Window share is NUMERIC / NUMERIC, which Redshift truncates to scale 4.
CREATE OR REPLACE TABLE gold.payment_mix AS
SELECT coalesce(p.method, 'unknown')                                      AS method,
       CASE coalesce(p.method, 'unknown')
            WHEN 'card'      THEN 'CARD'
            WHEN 'cash'      THEN 'CASH'
            WHEN 'wallet'    THEN 'DIGITAL'
            WHEN 'gift_card' THEN 'DIGITAL'
            ELSE 'OTHER'
       END                                                                AS method_family,
       if(p.method IS NOT NULL, 'captured', 'missing')                    AS method_status,
       COUNT(*)                                                           AS payment_count,
       SUM(p.amount)                                                      AS amount_total,
       CAST(floor(SUM(p.amount) / SUM(SUM(p.amount)) OVER (), 4) AS DECIMAL(38,4)) AS amount_share
FROM   silver.payments p
GROUP  BY p.method;
